/* This file contains the implementation of the PDFResult class.
 * It manages temporary PDF files generated by a phantomjs process.
 * All operations are designed to handle the lifecycle of these temporary files.
 */
"use strict" /* Enforces strict mode for cleaner code and fewer errors. */;


// Core Node.js modules for file system operations.
var fs   = require ( "fs" ) ,
	// A utility for creating and cleaning up temporary files and directories.
	tmp  = require ( "tmp" ) ,
	// Debugging utility, configured for 'phantomjs-pdf' namespace.
	debug = require ( 'debug' ) ( 'phantomjs-pdf' ) ;


/* Assigns the prototype of PDFResult to a variable 'method'
 * for easier and more concise method definitions. */
var method = PDFResult . prototype ;


/**
 * @class PDFResult
 * @param {Error|null} err - Any error encountered during PDF generation.
 * @param {string} tmpPath - The path to the temporary PDF file.
 * @param {boolean} deleteOnAction - Flag to indicate if the temporary file should be deleted after an action.
 * @constructor
 * Initializes a new instance of the PDFResult class.
 */
function PDFResult ( err , tmpPath , deleteOnAction )
{
	// Stores any error that occurred during PDF generation.
	this . _err             = err ;
	// Stores the path to the temporary file.
	this . _tmpPath         = tmpPath ;
	// Determines if the temporary file should be automatically deleted.
	this . _deleteOnAction  = deleteOnAction ;
	// Flag to track if the PDFResult object has been invalidated (e.g., after deletion).
	this . _invalid         = false ;
}


/**
 * Converts the temporary PDF file into a readable stream.
 * @returns {fs.ReadStream} A readable stream of the PDF file.
 * @throws {Error} If the PDFResult object has been invalidated.
 */
method . toStream = function ( )
{
	// Check if the object is still valid before proceeding.
	if ( this . _invalid )
	{
		throw new Error ( 'PDFResult became invalid after deletion!' ) ;
	}

	// Return a read stream from the temporary file path.
	return fs . createReadStream ( this . _tmpPath ) ;
} ;


/**
 * Reads the temporary PDF file into a Buffer.
 * @param {function(Buffer): void} callback - Callback function to receive the Buffer.
 * @throws {Error} If the PDFResult object has been invalidated.
 */
method . toBuffer = function ( callback )
{
	// Validate the object's state.
	if ( this . _invalid )
	{
		throw new Error ( 'PDFResult became invalid after deletion!' ) ;
	}

	// Array to hold chunks of data from the stream.
	var buffers = [ ] ;
	// Variable to store the concatenated buffer.
	var buffer ;
	// Create a readable stream from the temporary file.
	var stream = fs . createReadStream ( this . _tmpPath ) ;
	// Reference to the current PDFResult instance for use in callbacks.
	var resultObject = this ;


	// Event listener for incoming data chunks.
	stream . on ( 'data' , function ( data )
	{
		buffers . push ( data ) ; // Add each data chunk to the array.
	} ) ;


	// Event listener for the end of the stream.
	stream . on ( 'end' , function ( )
	{
		// Concatenate all data chunks into a single Buffer.
		buffer = Buffer . concat ( buffers ) ;

		// Check if the temporary file should be deleted after this action.
		if ( resultObject . _deleteOnAction )
		{
			resultObject . deleteTmpFile ( ) ;
		}
		// If a callback function is provided, invoke it with the buffer.
		if ( typeof callback === "function" )
		{
			callback ( buffer ) ;
		}
	} ) ;
} ;


/**
 * Returns the path to the temporary PDF file.
 * @returns {string} The file path.
 */
method . getTmpPath = function ( )
{
	return this . _tmpPath ;
} ;


/**
 * Saves the temporary PDF file to a specified permanent path.
 * @param {string} path - The destination path for the PDF file.
 * @param {function(): void} callback - Optional callback function to be executed upon completion.
 * @throws {Error} If the PDFResult object has been invalidated.
 */
method . toFile = function ( path , callback )
{
	// Ensure the object is in a valid state.
	if ( this . _invalid )
	{
		throw new Error ( 'PDFResult became invalid after deletion!' ) ;
	}

	// Create a writable stream to the target file.
	var outputStream = fs . createWriteStream ( path ) ;
	// Pipe the temporary file's content to the output file.
	var operation = fs . createReadStream ( this . _tmpPath ) . pipe ( outputStream ) ;
	// Hold reference to 'this' for use in the callback scope.
	var resultObject = this ;


	// Listen for the 'close' event, indicating the file has been successfully written.
	operation . on ( 'close' , function ( )
	{
		// If configured, delete the temporary file.
		if ( resultObject . _deleteOnAction )
		{
			resultObject . deleteTmpFile ( ) ;
		}
		// Execute the provided callback, if any.
		if ( typeof callback === "function" )
		{
			callback ( ) ;
		}
	} ) ;
} ;


/**
 * Deletes the temporary PDF file from the file system.
 * This method also invalidates the PDFResult object to prevent further operations.
 */
method . deleteTmpFile = function ( )
{
	// Capture 'this' for use within the asynchronous callback.
	var resultObject = this ;

	// Attempt to unlink (delete) the temporary file.
	fs . unlink ( this . _tmpPath , function ( err )
	{
		// If an error occurs during deletion, throw it.
		if ( err )
		{
			throw err ;
		}

		// Log successful deletion using the debug utility.
		debug ( 'Successfully deleted temporary file at "%s"' , resultObject . _tmpPath ) ;
		// Clear the path reference.
		resultObject . _tmpPath = '' ;
		// Mark the object as invalid to prevent subsequent operations on a non-existent file.
		resultObject . _invalid = true ;
	} ) ;
}


// Export the PDFResult constructor so it can be used by other modules.
module . exports = PDFResult ;